# Lunar Konstruksi - Formwork Fluid Layout + Hybrid Media Polish
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Phase([string]$Message) { Write-Host "[FLUID POLISH] $Message" -ForegroundColor Cyan }
function Fail([string]$Message) { Write-Host "[FLUID POLISH] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Decode([string]$Value) { [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }
function Write-Utf8([string]$Path,[string]$Content) {
  $parent=Split-Path -Parent $Path
  if($parent -and -not(Test-Path -LiteralPath $parent)){ New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  [IO.File]::WriteAllText($Path,$Content,(New-Object Text.UTF8Encoding($false)))
}

$repoRoot=(& git rev-parse --show-toplevel 2>$null)
if(-not $repoRoot){ Fail "Jalankan dari root repository Lunar." }
$repoRoot=$repoRoot.Trim(); Set-Location $repoRoot
Phase "Repo: $repoRoot"

$required=@(
  "components/site/formwork/home.tsx",
  "components/site/formwork/media.tsx",
  "components/site/formwork/data.ts",
  "components/site/formwork/about.tsx",
  "components/site/formwork/services.tsx",
  "components/site/formwork/projects.tsx"
)
$missing=@($required | Where-Object { -not(Test-Path -LiteralPath $_) })
if($missing.Count -gt 0){ $missing | ForEach-Object { Write-Host " - $_" }; Fail "Technical/Formwork frontend belum terdeteksi. Terapkan redesign terakhir lebih dulu." }

$tracked=& git status --porcelain --untracked-files=no
if($tracked){ Write-Host $tracked; Fail "Ada tracked changes. Commit/stash dulu supaya backup dan rollback jelas." }

$stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$backup=Join-Path $repoRoot ".lunar-backups/fluid-media-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null
foreach($rel in $required){
  $dest=Join-Path $backup $rel
  $parent=Split-Path -Parent $dest
  New-Item -ItemType Directory -Force -Path $parent | Out-Null
  Copy-Item -LiteralPath (Join-Path $repoRoot $rel) -Destination $dest -Force
}
Phase "Backup frontend: $backup"

$payload=@{}
$payload["components/site/formwork/home.tsx"]=""
$payload["components/site/formwork/media.tsx"]=""
$payload["components/site/formwork/data.ts"]=""
$payload["components/site/formwork/local-assets.ts"]=""
$payload["components/site/formwork/about.tsx"]=""
$payload["components/site/formwork/services.tsx"]=""
$payload["components/site/formwork/projects.tsx"]=""
$payload["public/lunar-static/hero-blueprint.svg"]=""
$payload["public/lunar-static/about-grid.svg"]=""
$payload["public/lunar-static/services-grid.svg"]=""
$payload["public/lunar-static/projects-grid.svg"]=""

foreach($entry in $payload.GetEnumerator()){
  Write-Utf8 (Join-Path $repoRoot $entry.Key) (Decode $entry.Value)
  Write-Host "[FLUID POLISH] write $($entry.Key)" -ForegroundColor DarkGray
}

# Detect local visual assets already available in public/.
# Entity records still prefer DB media. These local files are only one-off hero/decorative fallbacks.
$extensions=@(".jpg",".jpeg",".png",".webp",".avif")
$realFiles=@()
if(Test-Path -LiteralPath "public"){
  $realFiles=@(Get-ChildItem -LiteralPath "public" -Recurse -File | Where-Object {
    $extensions -contains $_.Extension.ToLowerInvariant() -and
    $_.FullName -notmatch '[\\/]lunar-static[\\/]' -and
    $_.Name -notmatch '(?i)(logo|favicon|icon|sprite|qr|badge)'
  })
}

function PublicUrl([IO.FileInfo]$File){
  if(-not $File){ return "" }
  $publicRoot=(Resolve-Path "public").Path
  $relative=$File.FullName.Substring($publicRoot.Length).Replace("\\","/")
  if(-not $relative.StartsWith("/")){ $relative="/"+$relative }
  return $relative
}

$scored=@($realFiles | ForEach-Object {
  $score=0
  $name=$_.Name
  $path=$_.FullName
  if($name -match '(?i)(hero|home|banner)'){ $score+=100 }
  if($name -match '(?i)(construction|konstruksi|building|project|site|work)'){ $score+=70 }
  if($name -match '(?i)(about|team|service|capability)'){ $score+=35 }
  if($path -match '(?i)(home|project|service|about)'){ $score+=20 }
  [PSCustomObject]@{File=$_;Score=$score}
} | Sort-Object Score -Descending)

$realUrls=@($scored | ForEach-Object { PublicUrl $_.File } | Select-Object -Unique)
$fallbacks=@(
  "/lunar-static/hero-blueprint.svg",
  "/lunar-static/about-grid.svg",
  "/lunar-static/services-grid.svg",
  "/lunar-static/projects-grid.svg"
)

function Pick([int]$Index,[string]$Fallback){
  if($realUrls.Count -gt $Index){ return [string]$realUrls[$Index] }
  return $Fallback
}

$decorative=@()
$decorative += $realUrls | Select-Object -First 8
foreach($fallback in $fallbacks){ if($decorative -notcontains $fallback){ $decorative += $fallback } }

function TsString([string]$Value){ return '"' + $Value.Replace('\\','\\\\').Replace('"','\\"') + '"' }
$decorativeLines=($decorative | ForEach-Object { "    " + (TsString $_) + "," }) -join "`n"
$config=@"
export const LOCAL_MEDIA = {
  hero: $(TsString (Pick 0 "/lunar-static/hero-blueprint.svg")),
  aboutHero: $(TsString (Pick 1 "/lunar-static/about-grid.svg")),
  servicesHero: $(TsString (Pick 2 "/lunar-static/services-grid.svg")),
  projectsHero: $(TsString (Pick 3 "/lunar-static/projects-grid.svg")),
  decorative: [
$decorativeLines
  ] as string[],
};

export function localMediaAt(index: number) {
  if (!LOCAL_MEDIA.decorative.length) return "";
  return LOCAL_MEDIA.decorative[index % LOCAL_MEDIA.decorative.length] ?? "";
}
"@
Write-Utf8 (Join-Path $repoRoot "components/site/formwork/local-assets.ts") $config

Write-Host ""
Phase "Hybrid media policy diterapkan."
Write-Host "  Hero/static   : local public/ -> DB -> technical placeholder" -ForegroundColor Green
Write-Host "  Projects      : DB masing-masing record -> placeholder" -ForegroundColor Green
Write-Host "  Services/team : DB record -> local fallback berbeda -> placeholder" -ForegroundColor Green
if($realUrls.Count -gt 0){
  Write-Host "  Local asset terdeteksi:" -ForegroundColor Cyan
  $realUrls | Select-Object -First 6 | ForEach-Object { Write-Host "    $_" }
}else{
  Write-Host "  Tidak ada foto lokal non-logo di public/. Technical SVG placeholder digunakan untuk visual statis." -ForegroundColor Yellow
}
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  npm run dev"
